import json
import sys

orders = json.load(sys.stdin)
totals = {}
for order in orders:
    totals[order['sku']] = totals.get(order['sku'], 0) + order['quantity'] * order['unit_cents']

print(json.dumps({
    'by_sku': dict(sorted(totals.items())),
    'total_cents': sum(totals.values()),
}))

